(() => {
  const ID = 'neon-drift';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, track, car, scoreEl, bestEl, gate, raf = 0, last = 0, progress = 0, score = 0, combo = 1, misses = 0, target = .5, pointer = false, running = false, paused = false, callbacks = {}, initialized = false;
  const $ = id => document.getElementById(id);
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function mount() {
    screen.innerHTML = `<div class="neon-drift-inner"><header class="neon-drift-hud"><button class="icon-button" data-drift-close aria-label="На главную">×</button><div class="neon-drift-brand"><small>TELEPLAY · ГОНКИ</small><b>Neon Drift</b></div><div class="neon-drift-stat"><small>СЧЁТ</small><b data-drift-score>0</b></div><button class="icon-button" data-drift-pause aria-label="Пауза">Ⅱ</button></header><div class="neon-drift-track" data-drift-track><span class="drift-line one"></span><span class="drift-line two"></span><span class="drift-gate" data-drift-gate></span><span class="drift-car" data-drift-car></span></div><p class="neon-drift-instruction">Веди палец влево и вправо, чтобы держать идеальную линию</p><p class="neon-drift-hint" data-drift-hint>Готовься к следующему повороту</p></div><div class="start-panel" data-drift-start><span class="panel-kicker">TELEPLAY · ГОНКИ</span><h2>Neon<br>Drift</h2><p>Собери чистую траекторию.<br>Каждый поворот ускоряет комбо.</p><button class="play-button large" data-drift-start-button>Начать заезд</button><div class="record">Лучший результат: <b data-drift-menu-best>0</b></div></div><div class="start-panel result-panel" data-drift-result hidden><span class="panel-kicker" data-result="kicker">ЗАЕЗД ОКОНЧЕН</span><h2 data-result="title">Чистая<br>линия!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Комбо <b data-result="combo">×1</b></span><span>Ошибки <b data-result="misses">0</b></span></div><button class="play-button large" data-drift-replay>Играть снова</button><button class="text-button" data-drift-home>На главную</button></div>`;
    track = screen.querySelector('[data-drift-track]'); car = screen.querySelector('[data-drift-car]'); gate = screen.querySelector('[data-drift-gate]'); scoreEl = screen.querySelector('[data-drift-score]'); bestEl = screen.querySelector('[data-drift-menu-best]');
  }
  function setTarget(event) { const rect = track.getBoundingClientRect(); target = Math.max(.22, Math.min(.78, (event.clientX - rect.left) / rect.width)); }
  function updateCar() { car.style.left = `${target * 100}%`; car.style.transform = `translateX(-50%) rotate(${(target - .5) * 25}deg)`; }
  function frame(time) {
    if (!running || paused) return; const dt = Math.min(.04, Math.max(0, (time - last) / 1000 || 0)); last = time; progress += dt * .11; const gateY = 8 + ((progress * 2.7) % 1) * 82; gate.style.top = `${gateY}%`; const gateTarget = .5 + Math.sin(progress * 14) * .25; gate.style.left = `${gateTarget * 100}%`; updateCar(); const distance = Math.abs(target - gateTarget); if (gateY > 76) { if (distance < .12) { score += 25 * combo; combo = Math.min(8, combo + 1); gate.classList.add('good'); screen.querySelector('[data-drift-hint]').textContent = 'ИДЕАЛЬНАЯ ЛИНИЯ'; haptic('light'); } else { misses += 1; combo = 1; score = Math.max(0, score - 15); screen.querySelector('[data-drift-hint]').textContent = 'Слишком резко — выровняйся'; haptic('heavy'); } scoreEl.textContent = Math.floor(score).toLocaleString('ru-RU'); } if (progress >= 1.0 || misses >= 5) finish(); else raf = requestAnimationFrame(frame);
  }
  function start() { cancelAnimationFrame(raf); running = true; paused = false; progress = 0; score = 0; combo = 1; misses = 0; target = .5; screen.querySelector('[data-drift-start]').hidden = true; screen.querySelector('[data-drift-result]').hidden = true; screen.querySelector('[data-drift-pause]').textContent = 'Ⅱ'; scoreEl.textContent = '0'; shell().emit('neon_drift_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); haptic('light'); last = performance.now(); raf = requestAnimationFrame(frame); }
  function finish() { if (!running) return; running = false; cancelAnimationFrame(raf); const previous = shell().getStats(ID), result = shell().saveResult(ID, Math.floor(score), { bestCombo: Math.max(previous.bestCombo || 1, combo), lastResult: { score: Math.floor(score), combo, misses, progress } }), reward = Math.max(1, Math.floor(score / 90)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score: Math.floor(score), metadata: { transactionId: `game:${ID}:run:${Date.now()}`, combo, misses, progress } }); shell().emit('neon_drift_finished', { gameId: ID, score: Math.floor(score), combo, misses, progress, reward }); shell().emit('game_finished', { gameId: ID, score: Math.floor(score), reward, maxCombo: combo, misses, distance: Math.floor(progress * 100) }); shell().ResultScreen.show(screen.querySelector('[data-drift-result]'), { score: Math.floor(score), bestScore: result.bestScore, reward, newRecord: result.newRecord, title: misses < 5 ? 'Чистая<br>линия!' : 'Занос<br>сорван', details: { combo: `×${combo}`, misses } }); screen.querySelector('[data-drift-result]').hidden = false; }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-drift-start]').hidden = false; screen.querySelector('[data-drift-result]').hidden = true; const stats = shell().getStats(ID); bestEl.textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; cancelAnimationFrame(raf); screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function pause() { if (!running) return; paused = !paused; screen.querySelector('[data-drift-pause]').textContent = paused ? '▶' : 'Ⅱ'; if (!paused) { last = performance.now(); raf = requestAnimationFrame(frame); } shell().emit(paused ? 'game_paused' : 'game_resumed', { gameId: ID }); }
  function init() { if (initialized) return; initialized = true; screen = $('neonDriftScreen'); mount(); screen.querySelector('[data-drift-start-button]').addEventListener('click', start); screen.querySelector('[data-drift-replay]').addEventListener('click', start); screen.querySelector('[data-drift-home]').addEventListener('click', close); screen.querySelector('[data-drift-close]').addEventListener('click', close); screen.querySelector('[data-drift-pause]').addEventListener('click', pause); track.addEventListener('pointerdown', event => { pointer = true; track.setPointerCapture(event.pointerId); setTarget(event); }); track.addEventListener('pointermove', event => { if (pointer) setTarget(event); }); track.addEventListener('pointerup', () => { pointer = false; }); document.addEventListener('visibilitychange', () => { if (document.hidden && !screen.hidden && running && !paused) pause(); }); }
  window.NeonDriftGame = { init, open, hide, close, start, restart: start, pause, resume: () => { if (paused) pause(); }, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
